# ------------------------------------------------------------------ assemblage
def decouper(texte):
    """Découpe une énumération sur les virgules hors parenthèses."""
    out, prof, cur = [], 0, ""
    for ch in texte:
        prof += (ch == "(") - (ch == ")")
        if ch == "," and prof == 0:
            out.append(cur.strip()); cur = ""
        else:
            cur += ch
    out.append(cur.strip())
    return [x for x in out if x]


def fiche_id(prefixe, *parts):
    return "-".join([prefixe] + [str(p) for p in parts])

def numeroter(prefixe, lignes):
    compte = {}
    for s in lignes:
        compte[s[0]] = compte.get(s[0], 0) + 1
        yield fiche_id(prefixe, s[0], compte[s[0]]), s
anat = [dict(id=i, systeme=s, region=r, volet=v, structure=st, lien=li, niveau=n)
        for i, (s, r, v, st, li, n) in numeroter("AN", ANAT)]
phys = [dict(id=i, systeme=s, volet=v, fonction=f, mecanisme_lien=m, niveau=n)
        for i, (s, v, f, m, n) in numeroter("PHY", PHYS)]
pp = []
for s, d in PP.items():
    for code, nom in VITE:
        mec, aff, n = d[code]
        pp.append(dict(id=fiche_id("PP", s, code), systeme=s, lettre=code, mecanisme_nom=nom, mecanisme=mec,
                       affections=decouper(aff), niveau=n))
semA = [dict(id="A-TRAME", type="trame", systeme="T", titre="Trame générale d'anamnèse", niveau="m",
             etapes=[dict(etape=e, contenu=c, ref=r) for e, c, r in TRAME_A])]
semA += [dict(id=i, type="specifique", systeme="T" if i not in ("A-SPE-1c", "A-SPE-1e") else "S11", titre=t, contenu=c, ref=r, niveau=n)
         for i, t, c, r, n in ANAM_SPEC]
for k, (ssp, s, m, q, rf, n) in enumerate(MOTIFS):
    semA.append(dict(id=fiche_id("A-MOT", k + 1), type="motif", ssp=ssp, systeme=s, titre=m, questions=q, drapeaux_rouges=rf, niveau=n))
semS = [dict(id=i, type="status", systeme=s, titre=t, manoeuvres=m, signes=g, epa=e, niveau=n, cs=cs)
        for i, s, t, m, g, e, n, cs in STATUS]
for k, (s, nom, sy, si, n) in enumerate(SYND):
    semS.append(dict(id=fiche_id("SY", k + 1), type="syndrome", systeme=s, titre=nom,
                     symptomes=decouper(sy), signes=decouper(si), niveau=n))
semM = [dict(id=i, titre=t, contenu=c, ref=r, niveau=n) for i, t, c, r, n in MGT]
semK = [dict(id=i, titre=t, contenu=c, ref=r, niveau=n) for i, t, c, r, n in KK]
trans = [dict(id=fiche_id("TR", i + 1), discipline=d, notion=no, contenu=c, niveau=n) for i, (d, no, c, n) in enumerate(TRANS)]

