sq = sorted(os.path.basename(p)[:-5] for p in glob.glob(os.path.join(PROG, "donnees", "fondamentales", "SF-*.json")))
def classe(nom):
    if nom.endswith("-anatomie") or nom.endswith("embryologie-histologie"): return "anatomie"
    if nom.endswith("-physiologie") or "biochimie" in nom or "sommeil" in nom or "neurobiologie" in nom or "psychologie" in nom: return "physiologie"
    if "physiopathologie" in nom: return "physiopathologie"
    return "transversales"
existant = {}
for n in sq:
    existant.setdefault(classe(n), []).append(n)

